"""Local checker and interpreter entry point."""
import argparse,json,sys
from pathlib import Path
from language import load,InvalidProgram,StaticError
from checker import check
from interpreter import run

def evaluate(text):
    try:p=load(text)
    except (InvalidProgram,TypeError,ValueError,RecursionError) as e:return {'accepted':False,'status':'invalid_program','message':str(e)}
    try:check(p)
    except StaticError as e:return {'accepted':False,'status':'static_error','message':str(e)}
    try:result=run(p)
    except (KeyError,InvalidProgram) as e:return {'accepted':True,'status':'other_runtime_error','message':str(e)}
    result['accepted']=True
    return result

if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('program');args=ap.parse_args()
    result=evaluate(Path(args.program).read_text());print(json.dumps(result,indent=2))
    sys.exit(0 if result['accepted'] and result['status']=='type_error' else 1)

"""Reed static checker. Types include result types and cell-write effects."""
from dataclasses import dataclass
from language import StaticError,kind,validate

@dataclass(frozen=True)
class Function:
    result:object
    writes:frozenset

def scalar(k):return frozenset((k,))

def shape(t):
    return ('fn',shape(t.result)) if isinstance(t,Function) else ('scalar',t)

def join(a,b,mode='branch',depth=0):
    if isinstance(a,Function) and isinstance(b,Function):
        writes=a.writes | b.writes
        return Function(join(a.result,b.result,mode,depth+1),writes)
    if isinstance(a,frozenset) and isinstance(b,frozenset):return a|b
    raise StaticError('incompatible types at join')

class Checker:
    def __init__(self,p):
        self.bounds={n:frozenset(d['types']) for n,d in p['cells'].items()}
        self.inputs=set(p['inputs'])
        self.coverage=set()
    def hit(self,tag):self.coverage.add(tag)
    def need(self,t,k):
        if t!=scalar(k):raise StaticError('expected '+k)
    def expr(self,e,env,facts):
        op=e[0];self.hit('expr:'+op)
        if op=='lit':return scalar(kind(e[1])),frozenset()
        if op=='var':
            if e[1] not in env:raise StaticError('unknown variable')
            return env[e[1]],frozenset()
        if op=='get':
            if e[1] not in facts:raise StaticError('unknown cell')
            return facts[e[1]],frozenset()
        if op=='is':
            if e[1] not in facts:raise StaticError('unknown cell')
            return scalar('bool'),frozenset()
        if op=='fn':
            inner=env.copy();fresh=self.bounds.copy()
            writes=self.block(e[1],inner,fresh)
            result,more=self.expr(e[2],inner,fresh)
            return Function(result,writes|more),frozenset()
        if op=='call':
            t,w=self.expr(e[1],env,facts)
            if not isinstance(t,Function):raise StaticError('expected function')
            self.hit('call:nested' if isinstance(t.result,Function) else 'call:scalar')
            for n in t.writes:facts[n]=self.bounds[n]
            return t.result,w|t.writes
        if op=='not':
            t,w=self.expr(e[1],env,facts);self.need(t,'bool');return scalar('bool'),w
        a,wa=self.expr(e[1],env,facts);b,wb=self.expr(e[2],env,facts)
        k='text' if op=='cat' else 'int';self.need(a,k);self.need(b,k)
        return scalar('bool' if op=='lt' else k),wa|wb
    def block(self,body,env,facts):
        writes=frozenset()
        for s in body:
            op=s[0];self.hit('stmt:'+op)
            if op in ('let','assign','set','eval'):
                e=s[1] if op=='eval' else s[2]
                t,w=self.expr(e,env,facts);writes|=w
                if op=='let':
                    if s[1] in env or s[1] in self.bounds:raise StaticError('name already bound')
                    env[s[1]]=t
                elif op=='assign':
                    if s[1] not in env or s[1] in self.inputs:raise StaticError('variable not assignable')
                    if shape(t)!=shape(env[s[1]]):raise StaticError('assignment shape')
                    env[s[1]]=t
                elif op=='set':
                    if s[1] not in self.bounds or not isinstance(t,frozenset) or not t<=self.bounds[s[1]]:raise StaticError('cell assignment')
                    facts[s[1]]=t;writes|=frozenset((s[1],))
                continue
            t,w=self.expr(s[1],env,facts);writes|=w
            if op=='if':
                self.need(t,'bool')
                ea,eb=env.copy(),env.copy();fa,fb=facts.copy(),facts.copy()
                guard=s[1]
                if guard[0]=='is':
                    n,k=guard[1:];fa[n]=facts[n]&scalar(k);fb[n]=facts[n]-scalar(k)
                wa=self.block(s[2],ea,fa) if all(fa.values()) else frozenset()
                wb=self.block(s[3],eb,fb) if all(fb.values()) else frozenset()
                viable=[(ea,fa)] if not all(fb.values()) else [(eb,fb)] if not all(fa.values()) else [(ea,fa),(eb,fb)]
                for n in env:env[n]=viable[0][0][n] if len(viable)==1 else join(ea[n],eb[n])
                for n in facts:facts[n]=viable[0][1][n] if len(viable)==1 else fa[n]|fb[n]
                writes|=wa|wb
            else:
                self.need(t,'int')
                memo={}
                def signature(t):
                    return (shape(t.result),t.writes) if isinstance(t,Function) else t
                for _ in range(64):
                    before=(env.copy(),facts.copy());next_env=env.copy();next_facts=facts.copy()
                    writes|=self.block(s[2],next_env,next_facts)
                    for n in env:
                        key=(n,signature(env[n]),signature(next_env[n]))
                        if key not in memo:memo[key]=join(env[n],next_env[n],'loop')
                        env[n]=memo[key]
                    for n in facts:facts[n]|=next_facts[n]
                    if before==(env,facts):break
                else:raise StaticError('analysis limit')
        return writes

def check(p,coverage=None):
    validate(p);c=Checker(p)
    env={n:scalar(kind(v)) for n,v in p['inputs'].items()}
    facts={n:scalar(kind(d['value'])) for n,d in p['cells'].items()}
    try:c.block(p['body'],env,facts)
    finally:
        if coverage is not None:coverage.update(c.coverage)
    return True

"""Concrete Reed interpreter, using an explicit stack of continuations."""
from dataclasses import dataclass
from language import RuntimeTypeError,StepLimit,MAX_STEPS,kind,validate

@dataclass
class Closure:
    body:list
    result:list
    captured:dict

class Machine:
    def __init__(self,p,limit=MAX_STEPS):
        self.cells={n:d['value'] for n,d in p['cells'].items()}
        self.steps=0;self.limit=limit;self.trace=[]
        self.values=[];self.work=[]
    def tick(self,label):
        if self.steps>=self.limit:raise StepLimit('step limit')
        self.steps+=1;self.trace.append({'step':self.steps,'operation':label})
    def require(self,v,k):
        actual='function' if isinstance(v,Closure) else kind(v)
        if actual!=k:raise RuntimeTypeError('expected '+k+', got '+actual)
    def schedule(self,body,env):
        for s in reversed(body):self.work.append(('statement',s,env))
    def execute(self,body,env):
        self.schedule(body,env)
        while self.work:
            tag,x,env=self.work.pop()
            if tag=='statement':
                op=x[0];self.tick('stmt:'+op)
                if op in ('let','assign','set'):
                    self.work.append((op,x[1],env));self.work.append(('expression',x[2],env))
                elif op=='eval':
                    self.work.append(('discard',None,env));self.work.append(('expression',x[1],env))
                else:
                    self.work.append((op,x,env));self.work.append(('expression',x[1],env))
            elif tag=='expression':
                op=x[0];self.tick('expr:'+op)
                if op=='lit':self.values.append(x[1])
                elif op=='var':self.values.append(env[x[1]])
                elif op=='get':self.values.append(self.cells[x[1]])
                elif op=='is':self.values.append(kind(self.cells[x[1]])==x[2])
                elif op=='fn':self.values.append(Closure(x[1],x[2],env.copy()))
                elif op in ('call','not'):
                    self.work.append((op,None,env));self.work.append(('expression',x[1],env))
                else:
                    self.work.append(('binary',op,env));self.work.append(('expression',x[2],env));self.work.append(('expression',x[1],env))
            elif tag in ('let','assign'):env[x]=self.values.pop()
            elif tag=='set':self.cells[x]=self.values.pop()
            elif tag=='discard':self.values.pop()
            elif tag=='call':
                f=self.values.pop();self.require(f,'function');local=f.captured.copy()
                self.work.append(('expression',f.result,local));self.schedule(f.body,local)
            elif tag=='not':
                a=self.values.pop();self.require(a,'bool');self.values.append(not a)
            elif tag=='binary':
                b=self.values.pop();a=self.values.pop();k='text' if x=='cat' else 'int'
                self.require(a,k);self.require(b,k)
                value=(a<b) if x=='lt' else (a+b)[:1024] if x=='cat' else ((a+b+2**31)%2**32)-2**31
                self.values.append(value)
            elif tag=='if':
                cond=self.values.pop();self.require(cond,'bool')
                self.work.append(('scope',set(env),env));self.schedule(x[2] if cond else x[3],env)
            elif tag=='repeat':
                count=self.values.pop();self.require(count,'int')
                old=set(env)
                for _ in range(max(0,min(3,count))):
                    self.work.append(('scope',old,env));self.schedule(x[2],env)
            elif tag=='scope':
                for n in set(env)-x:del env[n]
            else:raise AssertionError(tag)

def run(p,limit=MAX_STEPS):
    validate(p);m=Machine(p,limit)
    try:m.execute(p['body'],p['inputs'].copy())
    except RuntimeTypeError as e:return {'status':'type_error','message':str(e),'steps':m.steps,'trace':m.trace}
    except StepLimit:return {'status':'step_limit','steps':m.steps,'trace':m.trace}
    return {'status':'normal','steps':m.steps,'trace':m.trace}

"""Parser and structural limits for the Reed language."""
import json,re
MAX_BYTES=65536
MAX_NODES=512
MAX_DEPTH=32
MAX_STEPS=4096
KINDS=frozenset(('int','text','bool','unit'))
class InvalidProgram(Exception): pass
class StaticError(Exception): pass
class RuntimeTypeError(Exception): pass
class StepLimit(Exception): pass

def kind(v):
    if v is None:return 'unit'
    if type(v) is bool:return 'bool'
    if type(v) is int and -(2**31)<=v<2**31:return 'int'
    if type(v) is str and len(v)<=1024:return 'text'
    raise InvalidProgram('invalid literal')

def name(v):
    if not isinstance(v,str) or not re.fullmatch(r'[a-z][a-z0-9_]{0,23}',v):
        raise InvalidProgram('invalid name')
    return v

def load(text):
    if len(text.encode('utf-8'))>MAX_BYTES:raise InvalidProgram('file too large')
    def pairs(items):
        d={}
        for k,v in items:
            if k in d:raise InvalidProgram('duplicate key')
            d[k]=v
        return d
    try:p=json.loads(text,object_pairs_hook=pairs,parse_constant=lambda x:(_ for _ in ()).throw(InvalidProgram('nonfinite number')))
    except (ValueError,RecursionError) as e:raise InvalidProgram(str(e)) from e
    validate(p);return p

def validate(p):
    if type(p) is not dict or set(p)!={'cells','inputs','body'}:raise InvalidProgram('program keys')
    if type(p['cells']) is not dict or len(p['cells'])>8:raise InvalidProgram('cells')
    if type(p['inputs']) is not dict or len(p['inputs'])>8:raise InvalidProgram('inputs')
    for n,d in p['cells'].items():
        name(n)
        if type(d) is not dict or set(d)!={'types','value'}:raise InvalidProgram('cell definition')
        ts=d['types']
        if type(ts) is not list or not ts or any(type(t) is not str or t not in KINDS for t in ts) or len(set(ts))!=len(ts):raise InvalidProgram('cell types')
        if kind(d['value']) not in ts:raise InvalidProgram('cell initial value')
    for n,v in p['inputs'].items():
        name(n);kind(v)
        if n in p['cells']:raise InvalidProgram('duplicate name')
    count=0
    def expr(e,depth):
        nonlocal count
        count+=1
        if depth>MAX_DEPTH or count>MAX_NODES:raise InvalidProgram('AST limit')
        if type(e) is not list or not e or type(e[0]) is not str:raise InvalidProgram('expression')
        op=e[0]
        arities={'lit':2,'var':2,'get':2,'add':3,'cat':3,'lt':3,'not':2,'is':3,'call':2,'fn':3}
        if op not in arities or len(e)!=arities[op]:raise InvalidProgram('expression operator/arity')
        if op=='lit':kind(e[1])
        elif op in ('var','get'):name(e[1])
        elif op=='is':
            name(e[1])
            if e[2] not in KINDS:raise InvalidProgram('is kind')
        elif op=='fn':block(e[1],depth+1);expr(e[2],depth+1)
        else:
            for x in e[1:]:expr(x,depth+1)
    def block(b,depth):
        nonlocal count
        if type(b) is not list or len(b)>128 or depth>MAX_DEPTH:raise InvalidProgram('block')
        for s in b:
            count+=1
            if count>MAX_NODES or type(s) is not list or not s or type(s[0]) is not str:raise InvalidProgram('statement')
            op=s[0]
            arities={'let':3,'assign':3,'set':3,'eval':2,'if':4,'repeat':3}
            if op not in arities or len(s)!=arities[op]:raise InvalidProgram('statement operator/arity')
            if op in ('let','assign','set'):name(s[1]);expr(s[2],depth+1)
            elif op=='eval':expr(s[1],depth+1)
            elif op=='if':expr(s[1],depth+1);block(s[2],depth+1);block(s[3],depth+1)
            else:expr(s[1],depth+1);block(s[2],depth+1)
    block(p['body'],1)
    return count
